import type { Metadata } from 'next'

const SITE_NAME = 'FLAME Squash Club'
const DEFAULT_IMAGE = { url: '/og-image.jpg', width: 1200, height: 630, alt: SITE_NAME }

type Image = { url: string; width: number; height: number; alt: string }

/** A card from public/, generated by scripts/og_cards.py (all are 1200x630). */
export function ogCard(file: string, alt: string): Image {
  return { url: `/${file}`, width: 1200, height: 630, alt }
}

/**
 * Per-page metadata, including the parts the root layout would otherwise hand
 * down unchanged.
 *
 * Next.js inherits `openGraph`, `twitter` and `alternates` from the layout as
 * whole objects; a page's own `title` does not reach into them. Without this,
 * every link preview (WhatsApp, Instagram, iMessage) shows the homepage's
 * title, text and photo, and every page declares the homepage as its
 * canonical URL, which tells search engines the page is a duplicate of it.
 *
 * `path` is relative to metadataBase in app/layout.tsx.
 */
export function pageMetadata(
  { title, description, path, image = DEFAULT_IMAGE }:
  { title: string; description: string; path: string; image?: Image },
): Metadata {
  const full = `${title} | ${SITE_NAME}`
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: 'website',
      url: path,
      siteName: SITE_NAME,
      locale: 'en_IN',
      title: full,
      description,
      images: [image],
    },
    twitter: {
      card: 'summary_large_image',
      title: full,
      description,
      images: [image.url],
    },
  }
}
